  var v_sediment: f32 = (v_m.y * (1.0f - min(1.0f, cw_divide_f32(v_out, max(b_field[v_i].y, 1e-7f)))));
  if ((v_x > 0i)) {
    v_sediment = (v_sediment + cw_divide_f32((b_input[(v_i - 1i)].y * b_flux[(v_i - 1i)].y), max(b_field[(v_i - 1i)].y, 1e-7f)));
  }
  if ((v_x < (cw_params.p_n - 1i))) {
    v_sediment = (v_sediment + cw_divide_f32((b_input[(v_i + 1i)].y * b_flux[(v_i + 1i)].x), max(b_field[(v_i + 1i)].y, 1e-7f)));
  }
  if ((v_z > 0i)) {
    v_sediment = (v_sediment + cw_divide_f32((b_input[(v_i - cw_params.p_n)].y * b_flux[(v_i - cw_params.p_n)].w), max(b_field[(v_i - cw_params.p_n)].y, 1e-7f)));
  }
  if ((v_z < (cw_params.p_n - 1i))) {
    v_sediment = (v_sediment + cw_divide_f32((b_input[(v_i + cw_params.p_n)].y * b_flux[(v_i + cw_params.p_n)].z), max(b_field[(v_i + cw_params.p_n)].y, 1e-7f)));
  }
